namespace Context.Host.Api;

/// <summary>
/// <c>GET /api/auth/token</c> — the ONLY endpoint besides <c>/health</c> and the static SPA shell
/// left unauthenticated. Exists so the Angular Dashboard (which has no other way to learn the
/// bearer token generated by <c>context claude install</c>) can bootstrap itself.
/// <para/>
/// This is safe under the same-origin policy, which is exactly what makes it safe: a cross-origin
/// page's JS cannot read this response unless the server's CORS policy explicitly allows that
/// origin (see <c>Program.cs</c> — restricted to the known dev origins, and applied only in
/// Development; Production has no CORS policy at all, so no cross-origin page can read this
/// response there, full stop). The Dashboard itself, loaded same-origin (production, served from
/// this host's own wwwroot) or from an explicitly allow-listed dev origin, can always read it. The
/// host's loopback-only bind (<c>ContextHostOptions.BindHost</c>) is the other half of the trust
/// boundary: only local processes/browsers can reach this port in the first place.
/// </summary>
public static class BootstrapEndpoints
{
    public static void MapBootstrapEndpoints(this WebApplication app)
    {
        app.MapGet("/api/auth/token", GetToken);
    }

    private static IResult GetToken(HostProjectContext project) =>
        Results.Ok(new BootstrapTokenResponse(project.BearerToken));
}

public sealed record BootstrapTokenResponse(string? Token);
